/*
 * A069760  Frobenius number of the numerical semigroup generated by
 *          consecutive centered square numbers.
 * https://oeis.org/A069760
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, nonn
 * Formula:   a(n) = 4*n^4 + 16*n^3 + 20*n^2 + 8*n - 1
 * Range:     u8 n <= 1, u16 n <= 10, u32 n <= 180, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    seq_t x = (seq_t)n;
    seq_t v = 4;        /* start with coefficient of n^4 */
    v = v * x + 16;     /* add coefficient of n^3 */
    v = v * x + 20;     /* add coefficient of n^2 */
    v = v * x + 8;      /* add coefficient of n   */
    v = v * x - 1;      /* add constant term      */
    return v;
}
